const listProjectionArtifactDependencies = `-- name: ListProjectionArtifactDependencies :many
SELECT id,
    artifact_id,
    tournament_id,
    roster_id,
    dependency_kind,
    depends_on_artifact_id,
    official_result_revision_id,
    official_result_series_id,
    golden_position_commit_id,
    created_at
FROM projection_dependencies
WHERE artifact_id = $1
    AND tournament_id = $2
    AND roster_id = $3
ORDER BY created_at, id
`

type ListProjectionArtifactDependenciesParams struct {
	ArtifactID   uuid.UUID
	TournamentID uuid.UUID
	RosterID     uuid.UUID
}

func (q *Queries) ListProjectionArtifactDependencies(ctx context.Context, arg ListProjectionArtifactDependenciesParams) ([]ProjectionDependency, error) {
	rows, err := q.db.Query(ctx, listProjectionArtifactDependencies, arg.ArtifactID, arg.TournamentID, arg.RosterID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProjectionDependency{}
	for rows.Next() {
		var i ProjectionDependency
		if err := rows.Scan(
			&i.ID,
			&i.ArtifactID,
			&i.TournamentID,
			&i.RosterID,
			&i.DependencyKind,
			&i.DependsOnArtifactID,
			&i.OfficialResultRevisionID,
			&i.OfficialResultSeriesID,
			&i.GoldenPositionCommitID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

